persuasion_principles:
 {
  "Reciprocity": {
    "Explanation": "The sender is asking for help and advice from the recipients in return for nothing. He is creating an expectation that if the recipients provide him with information, he will reciprocate by thanking them or providing them with something in return."
  },
  "Scarcity": {
    "Explanation": "There is no implied scarcity in the email. The sender is not creating a sense of urgency or limiting the availability of the information or solution being requested."
  },
  "Authority": {
    "Explanation": "The email does not claim or display any authority. The sender is not using a recognized institution, title, or role to increase his credibility or persuasive power."
  },
  "Commitment/Consistency": {
    "Explanation": "There is no reference to prior behavior or choices in the email. The sender is not using the principle of commitment and consistency to push further action."
  },
  "Liking": {
    "Explanation": "The email does not use familiarity, flattery, or personalization to build trust or rapport with the recipients. There is no attempt to make the sender or the email more likable."
  },
  "Social proof": {
    "Explanation": "The email does not reference other people's participation or endorsement. There is no attempt to use social proof to increase the persuasive power of the email."
  }
}

